{"hypotheses": [
  {
    "root_cause": "Forecast pipeline's own processing capacity is the bottleneck.",
    "mechanism": "The forecast-pipeline deployment/pod is CPU-throttled, memory-pressured, or running a performance regression under increased job volume, causing internal stages to queue and end-to-end p95 duration to exceed 5s.",
    "statement": "The fault originates inside the forecast-pipeline itself, not in an upstream dependency."
  },
  {
    "root_cause": "PostgreSQL is degraded or overloaded.",
    "mechanism": "The shared postgres instance is experiencing slow queries, lock contention, or connection-pool exhaustion on the forecast-pipeline's read/write path, making database calls block and inflating pipeline duration.",
    "statement": "The forecast-pipeline is slow because its database dependency is degraded."
  },
  {
    "root_cause": "Forecast-service is degraded or overutilized.",
    "mechanism": "The forecast-service ML inference/serving path is responding slowly to forecast-pipeline calls due to model latency, resource saturation, or downstream postgres delays.",
    "statement": "The forecast-pipeline is slow because its ML forecast-service dependency is degraded."
  },
  {
    "root_cause": "Feature-service is degraded or overutilized.",
    "mechanism": "Feature-service is returning feature data to forecast-pipeline more slowly than normal due to its own CPU/GC pressure, request pile-up, or downstream postgres contention.",
    "statement": "The forecast-pipeline is slow because feature-service, an upstream provider, has elevated latency."
  },
  {
    "root_cause": "Planning-api is degraded or overloaded.",
    "mechanism": "Planning-api is saturated by critical grid-operator traffic or its own resource limits, causing forecast-pipeline calls to planning-api to stall, queue, or retry.",
    "statement": "The forecast-pipeline is slow because its critical planning-api dependency is overloaded."
  }
]}
